import type { DropdownIconButtonProps } from "./dropdown-icon-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "DropdownIconButton";

export const DropdownIconButtonClasses = {
  root: "exp-textura_dropdown-icon-button",
  sm: "exp-textura_dropdown-icon-button_sm",
  leadingIcon: "exp-textura_dropdown-icon-button_leading_icon",
  dropdownIcon: "exp-textura_dropdown-icon-button_dropdown_icon",
};

const generateStyles = (props: DropdownIconButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<DropdownIconButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
      ),
    [theme, variant, styleSlotsProp],
  );

  // TODO: replace theme.buttonIconDropdown.primary.* with theme.buttonIconDropdown.* once Figma tokens land
  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    height: theme.toRem(32),
    padding: `0 ${theme.toRem(theme.spacing[8])}`,
    borderRadius: theme.buttonIconDropdown.border.radius,
    cursor: "pointer",
    border: "none",
    backgroundColor: theme.buttonIconDropdown.color.background.enabled,
    color: theme.buttonIconDropdown.color.content.enabled,
    transition: "background-color 0.2s, border-color 0.2s, color 0.2s",

    [`& .${DropdownIconButtonClasses.leadingIcon}`]: {
      fontSize: theme.toRem(16),
      ...styleSlots?.leadingIcon,
    },

    [`& .${DropdownIconButtonClasses.dropdownIcon}`]: {
      fontSize: theme.toRem(14),
      ...styleSlots?.dropdownIcon,
    },

    "&:hover": {
      backgroundColor: theme.buttonIconDropdown.color.background.hover,
      color: theme.buttonIconDropdown.color.content.hover,
      ...styleSlots?.hover,
    },

    "&:active": {
      backgroundColor: theme.buttonIconDropdown.color.background.pressed,
      color: theme.buttonIconDropdown.color.content.pressed,
      ...styleSlots?.pressed,
    },

    "&[data-selected='true']": {
      backgroundColor: theme.buttonIconDropdown.color.background.selected,
      color: theme.buttonIconDropdown.color.content.selected,
      ...styleSlots?.selected,
    },

    "&:disabled, &[aria-disabled='true']": {
      backgroundColor: theme.buttonIconDropdown.color.background.disabled,
      color: theme.buttonIconDropdown.color.content.disabled,
      cursor: "not-allowed",
      ...styleSlots?.disabled,
    },

    "&:focus-visible": {
      ...styleSlots?.focus,
    },

    [`&.${DropdownIconButtonClasses.sm}`]: {
      height: theme.toRem(24),
      padding: `0 ${theme.toRem(theme.spacing[4])}`,
      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps("selected");

export const StyledDropdownIconButton = styled("button", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<DropdownIconButtonProps>((props) => generateStyles(props));
